BEGIN;
WITH inserted AS (
  RETURNING id, transaction_ref
) SELECT json_agg(json_build_object('id',id,'transactionRef',transaction_ref)) AS inserted_outbox FROM inserted;
SELECT json_build_object(
 'outbox', (SELECT json_agg(json_build_object('id',id,'transactionRef',transaction_ref,'status',status)) FROM outbox_messages WHERE transaction_ref LIKE 'EVD-OUTBOX-DLQ-20260803T%' ),
 'deadLetters', (SELECT json_agg(json_build_object('id',id,'eventId',event_id,'status',status,'transferRef',transfer_ref,'outboxEventId',outbox_event_id,'replayRequestedBy',replay_requested_by,'replayApprovedBy',replay_approved_by)) FROM outbox_dead_letters WHERE transfer_ref LIKE 'EVD-DLQ-%')
) AS fixture_summary;
COMMIT;
